// ACL: translate the legacy account record into the bubble's language
public sealed class LegacyAccountTranslator
{
    public OverdraftAccount ToDomain(LegacyAcctRow row) => new(
        AccountId: new AccountId(row.ACCT_NO.Trim()),
        Arranged: new Money(row.OD_LMT_PNC / 100m, Currency.Parse(row.CCY_CD)),
        Status: row.STAT_CD switch
        {
            "A" => AccountStatus.Active,
            "D" or "DR" => AccountStatus.Dormant,            // two legacy codes mean the same thing
            "B" => AccountStatus.Blocked,
            _ => throw new UnknownLegacyCodeException(row.STAT_CD)
        },
        IsJoint: row.JNT_FLG == "Y" || row.HOLDER_CNT > 1);
}

// Autonomous bubble: keep its own store in sync from legacy CDC events, through the ACL
public sealed class LegacyAccountChangedHandler(LegacyAccountTranslator acl, OverdraftDb db)
{
    public async Task HandleAsync(LegacyCdcEvent<LegacyAcctRow> e, CancellationToken ct)
    {
        var account = acl.ToDomain(e.After);
        await db.Accounts.UpsertAsync(account, version: e.LogSequence, ct);   // ignore older versions
